<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_login('provider');$id=(int)($_GET['id']??0);
$stmt=db()->prepare('SELECT p.id AS provider_id,p.verification_status,tr.*,(SELECT COUNT(*) FROM provider_bids pb WHERE pb.trip_request_id=tr.id AND pb.provider_id=p.id) AS already_bid FROM providers p INNER JOIN trip_requests tr ON tr.id=? WHERE p.user_id=? LIMIT 1');$stmt->bind_param('ii',$id,$user['id']);$stmt->execute();$request=$stmt->get_result()->fetch_assoc();if(!$request){http_response_code(404);exit('Request not found.');}
if(!in_array($request['verification_status'],['verified','trusted','preferred'],true)){http_response_code(403);exit('Provider verification is required.');}
$page_title='Request '.$request['request_number'];require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="h3 mb-1"><?=e($request['request_number'])?></h1><p class="text-secondary mb-0"><?=e($request['origin'])?> → <?=e($request['destination'])?></p></div><span class="badge text-bg-light"><?=e(str_replace('_',' ',$request['status']))?></span></div><div class="row g-4"><div class="col-lg-8"><div class="card p-4"><h2 class="h5">Trip requirements</h2><div class="row g-3"><div class="col-md-4"><strong>Dates</strong><br><?=e($request['start_date'])?> → <?=e($request['end_date'])?></div><div class="col-md-4"><strong>Travelers</strong><br><?=e((string)$request['adults'])?> adults, <?=e((string)$request['children'])?> children</div><div class="col-md-4"><strong>Budget</strong><br><?=e($request['currency'])?> <?=number_format((float)$request['budget_min'])?> – <?=number_format((float)$request['budget_max'])?></div></div><hr><h3 class="h6">Requirements</h3><p class="mb-0"><?=nl2br(e($request['description']?:'No additional requirements provided.'))?></p></div></div><div class="col-lg-4"><div class="card p-4"><h2 class="h5">Respond</h2><?php if($request['already_bid']):?><div class="alert alert-success">You have already submitted an offer for this request.</div><a class="btn btn-outline-dark w-100" href="/provider/dashboard.php">Back to requests</a><?php elseif(!in_array($request['status'],['published','receiving_offers'],true)||(!empty($request['expires_at'])&&strtotime($request['expires_at'])<time())):?><div class="alert alert-secondary">This request is no longer accepting offers.</div><?php else:?><a class="btn btn-dark w-100" href="/provider/bid-add.php?request_id=<?=$request['id']?>">Submit offer</a><?php endif;?></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>